            // all of the region highlighting machinery only deals with those.
            let guar = self.emit_err(
                var_origin.span(),
                Ty::new_fn_ptr(self.cx.tcx, expected),
                Ty::new_fn_ptr(self.cx.tcx, found),
                *trait_item_def_id,
            );
            return Some(guar);
        }
        None
    }
